def get_rule_key(item_id):
    try:
        idx = int(item_id)
        for key in SPECIAL_RULES_MAP.keys():
            if "-" in key:
                start, end = map(int, key.split("-"))
                if start <= idx <= end: return key
            elif int(key) == idx: return key
    except: pass
    return None
